-- ============================================================
-- Миграция 05: оборудование по спецификациям всех разделов (листы СО1/СО2)
-- Разделы: АОВ-К00, АОВ-D, АОВ-C1, АОВ-C2, АОВ-C3, АДИС, АЭС
--
-- Что загружается: комплекты конечного оборудования, «Материалы и монтажные изделия»,
--   «Кабельные конструкции». НЕ загружаются: шкафы и их начинка (раздел «Щиты»)
--   и кабельная продукция (раздел «Кабели»).
-- Исправляет старую загрузку, где в последний комплект (VRF / конвекторы) попадали
--   кабели и материалы, и добавляет недостающие позиции (датчики к ШС1-C1…D3 в АДИС,
--   пульты VRF в C1/C3, материалы и лотки в АОВ-К00 и т.д.).
--
-- История монтажа сохраняется: старая позиция сопоставляется с новой по
--   (раздел, поз., марка/наименование) и ОБНОВЛЯЕТСЯ, а не пересоздаётся.
--   Устаревшие позиции без записей монтажа удаляются; с записями — остаются,
--   их список выводится в конце.
-- Выполнить ОДИН раз: Supabase → SQL Editor → New query → Run
-- ============================================================

drop table if exists eq_new;
create temp table eq_new (rid serial, section text, group_name text, pos text, name text, model text, supplier text, unit text, qty numeric);


-- ключ сравнения: марка (без пробелов/регистра), если пусто — начало наименования
drop table if exists eq_map;
create temp table eq_map as
with cand as (
  select n.rid, e.id as eid,
    case when lower(regexp_replace(coalesce(nullif(e.model,''), left(e.name,40)),'\s','','g'))
            = lower(regexp_replace(coalesce(nullif(n.model,''), left(n.name,40)),'\s','','g')) then 0
         when left(lower(regexp_replace(coalesce(e.name,''),'\s','','g')),15)
            = left(lower(regexp_replace(coalesce(n.name,''),'\s','','g')),15) then 1
         when coalesce(e.group_name,'') = n.group_name then 1
         else 2 end as prio
  from eq_new n join equipment e on e.section = n.section and coalesce(e.pos,'') = n.pos
),
best_new as (select distinct on (rid) rid, eid, prio from cand where prio < 2 order by rid, prio, eid)
select distinct on (eid) rid, eid from best_new order by eid, prio, rid;

-- 0) перенести отметки «Допуск» на переименованные комплекты (если комплект целиком переехал в один)
update readiness r set front = x.new_g
from (
  select e.section, coalesce(e.group_name,'') as old_g, min(n.group_name) as new_g
  from eq_map m join equipment e on e.id = m.eid join eq_new n on n.rid = m.rid
  group by 1, 2 having count(distinct n.group_name) = 1
) x
where r.kind = 'equipment' and r.section = x.section and r.front = x.old_g and x.old_g <> x.new_g
  and not exists (select 1 from readiness r2 where r2.kind = 'equipment' and r2.section = x.section and r2.front = x.new_g);

-- 1) обновить сопоставленные (журнал монтажа остаётся привязан)
update equipment e set group_name = n.group_name, pos = n.pos, name = n.name, model = n.model,
  supplier = n.supplier, unit = n.unit, qty = n.qty, updated_at = now()
from eq_map m join eq_new n on n.rid = m.rid
where e.id = m.eid;

-- 2) удалить устаревшие без истории монтажа
delete from equipment e
where e.section in (select distinct section from eq_new)
  and e.id not in (select eid from eq_map)
  and e.id not in (select equipment_id from equipment_logs);

-- 3) добавить новые
select n.section, n.group_name, n.pos, n.name, n.model, n.supplier, n.unit, n.qty
from eq_new n where n.rid not in (select rid from eq_map)
order by n.rid;

-- 4) итог
select 'итого' as что, section, count(*)::text as кол_во, null as комплект, null as поз, null as наименование
from equipment group by section
union all
select 'устарела, но есть монтаж', e.section, null, e.group_name, e.pos, left(e.name,80)
from equipment e
where e.section in (select distinct section from eq_new)
  and e.id not in (select eid from eq_map)
  and e.id in (select equipment_id from equipment_logs)
order by 1 desc, 2;
